<script setup lang="ts">
import{onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{vendorAPI}from'../../services/api';import type{VendorOrderShare}from'../../services/api';import StatusBadge from'../../components/StatusBadge.vue';
const route=useRoute(),router=useRouter(),items=ref<VendorOrderShare[]>([]),loading=ref(true),error=ref(''),status=ref(typeof route.query.status==='string'?route.query.status:''),page=ref(1),totalPages=ref(1),tabs=['','pending','confirmed','shipped','received','cancelled'];
async function load(){loading.value=true;error.value='';try{const r=await vendorAPI.getOrders({status:status.value,page:page.value,per_page:20});items.value=r.items;totalPages.value=r.totalPages}catch(e:unknown){error.value=e instanceof Error?e.message:'Orders could not be loaded.'}finally{loading.value=false}}watch(status,()=>{page.value=1;void router.replace({query:{status:status.value||undefined,page:page.value>1?String(page.value):undefined}});void load()});function date(v:string){return new Date(v).toLocaleDateString('en-KE',{day:'numeric',month:'short',year:'numeric'})}onMounted(load)
</script><template><main class="vendor-main"><header class="page-head"><p>FULFILMENT</p><h1>My Orders</h1></header><nav class="tabs" aria-label="Order statuses"><button v-for="tab in tabs" :key="tab" :class="{active:status===tab}" @click="status=tab">{{tab?tab.charAt(0).toUpperCase()+tab.slice(1):'All'}}</button></nav><div v-if="loading" class="state">Loading orders...</div><div v-else-if="error" class="state error">{{error}}</div><div v-else-if="!items.length" class="state">No orders found.</div><div v-else class="order-table"><table><thead><tr><th>Order</th><th>Date</th><th>Items</th><th>Status</th><th>Subtotal</th><th></th></tr></thead><tbody><tr v-for="o in items" :key="o.order_id"><td data-label="Order"><strong>{{o.order_number}}</strong></td><td data-label="Date">{{date(o.placed_at)}}</td><td data-label="Items">{{o.items.reduce((n,i)=>n+i.quantity,0)}} items</td><td data-label="Status"><StatusBadge :status="o.status"/></td><td data-label="Subtotal">KSh {{o.subtotal.toLocaleString()}}</td><td><router-link :to="`/vendor/orders/${o.order_id}`">View</router-link></td></tr></tbody></table></div></main></template><style scoped>.vendor-main{padding:18px 28px}.page-head p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.page-head h1{margin:4px 0 16px}.tabs{display:flex;gap:5px;margin-bottom:14px;overflow:auto}.tabs button{height:38px;padding:0 12px;border:1px solid #dbe3ec;border-radius:6px;background:#fff;color:#526579;font-weight:750}.tabs button.active{border-color:#075397;background:#075397;color:#fff}.order-table{border:1px solid #e6ebf1;border-radius:8px;background:#fff;overflow:hidden}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #edf0f3;text-align:left}th{color:#64748b;font-size:.72rem}.state{padding:30px;border:1px solid #e6ebf1;border-radius:8px;text-align:center;background:#fff}.error{color:#b42318}@media(max-width:700px){.vendor-main{padding:14px}.order-table{border:0;background:transparent}table,tbody,tr,td{display:block}thead{display:none}tr{margin-bottom:10px;padding:10px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}td{display:flex;justify-content:space-between;border:0;padding:7px}td::before{content:attr(data-label);color:#64748b;font-weight:700}}</style>